 Future<dynamic> getData(String path)async{final c=HttpClient()..connectionTimeout=const Duration(seconds:12);try{final r=await (await c.getUrl(Uri.https('api.alquran.cloud',path))).close().timeout(const Duration(seconds:18));final body=await r.transform(utf8.decoder).join();if(r.statusCode!=200)throw Exception('network');final j=jsonDecode(body) as Map<String,dynamic>;if(j['code']!=200)throw Exception('api');return j['data'];}finally{c.close(force:true);}}
