 Future<void> _play()async{if(ayahs.isEmpty)return;final url=ayahs[ayahIndex]['audio']?.toString()??'';if(url.isEmpty){setState(()=>error='التسجيل غير متاح لهذه الآية.');return;}try{await player.setPlaybackRate(playbackRate);await player.play(UrlSource(url));if(mounted)setState(()=>playing=true);}catch(_){if(mounted)setState(()=>error='تعذر تشغيل الصوت. تحقق من الإنترنت.');}}
 Future<void> _onAudioComplete()async{if(!mounted||ayahs.isEmpty)return;if(repeatCount==0||repeatDone+1<repeatCount){setState(()=>repeatDone++);await _play();return;}repeatDone=0;if(autoAdvance){await _next();}else if(mounted){setState(()=>playing=false);}}
