 Future<void> _toggle()async{if(playing){await player.pause();if(mounted)setState(()=>playing=false);}else{await _play();}}
 Future<void> _next()async{if(ayahIndex+1>=ayahs.length){if(mounted)setState(()=>playing=false);return;}setState((){ayahIndex++;repeatDone=0;position=Duration.zero;duration=Duration.zero;});final p=await SharedPreferences.getInstance();await p.setInt('quran_last_ayah',ayahIndex+1);await _play();}
 Future<void> _prev()async{if(ayahIndex==0)return;setState(()=>ayahIndex--);final p=await SharedPreferences.getInstance();await p.setInt('quran_last_ayah',ayahIndex+1);await _play();}
